class Table:
    """Read-only: who holds how much of a scarce resource on this machine, verified
    by the instrument or claimed by the holder. No row is invented: a holder the
    instrument cannot attribute to a program is reported under its process image
    with evidence verified and no account when the platform gives none. The
    table changes nothing."""

    def resources(self) -> ResourcesResult:
        """The resources this machine's instrument and adapters can report."""
        raise NotImplementedError

    def holders(self, resource: str, fresh: bool) -> HoldersResult:
        """Who holds resource now. fresh reads the instrument again; otherwise the
        last sample within its age bound. Gated by
        abstraction.resource/table.read on resource account; a program always
        sees its own rows, and capacity, held and observed describe the machine
        to every caller."""
        raise NotImplementedError


class TableClient(Table):
    """Calls abstraction.resource/table@1 through a transport that exchanges frames."""

    def __init__(self, transport):
        self._transport = transport

    def resources(self) -> ResourcesResult:
        _args = _TableResourcesArguments()
        _arguments = _service_encode(_write_oa_table_resources_arguments, _args, 1)
        _service_decode(_read_oa_table_resources_arguments, _arguments, 1)
        _request = _service_request("abstraction.resource/table@1", "Resources", _arguments)
        _payload = _service_response(self._transport.exchange_frame(_request), "abstraction.resource/table@1", "Resources")
        _result = _service_decode(_read_oa_table_resources_result, _payload, 1)
        return _result.value

    def holders(self, resource: str, fresh: bool) -> HoldersResult:
        _service_check("string", resource)
        _service_check("bool", fresh)
        _args = _TableHoldersArguments()
        _args.resource = resource
        _args.fresh = fresh
        _arguments = _service_encode(_write_oa_table_holders_arguments, _args, 1)
        _service_decode(_read_oa_table_holders_arguments, _arguments, 1)
        _request = _service_request("abstraction.resource/table@1", "Holders", _arguments)
        _payload = _service_response(self._transport.exchange_frame(_request), "abstraction.resource/table@1", "Holders")
        _result = _service_decode(_read_oa_table_holders_result, _payload, 1)
        return _result.value


class Leases:
    """Leases on a scarce resource, asked back on demand. A holder that predates OA
    is an attached holder: the service yields on its behalf through the host's
    own mechanism (LM Studio unload, Ollama keep_alive 0, ComfyUI free) and
    records the result as if answered. Every ask, yield and refusal is a record
    with the asker, the holder, the amount and the time. Version 1 kills nothing
    and boosts nothing."""

    def acquire(self, resource: str, amount: int, wait_ms: int) -> AcquireResult:
        """Ask to reserve amount bytes for admission of the bound caller, waiting
        up to wait_ms (0..120000) for holders to yield. The reservation is not a
        physical usage quota. Order: the rights decision for
        abstraction.resource/hold on resource (not_permitted, or unavailable
        when the decision point cannot answer), then the table (insufficient
        when capacity is known and amount exceeds it), then holders are asked in
        the service's order and the result is acquired or holders_refused.
        Nothing is killed."""
        raise NotImplementedError

    def renew(self, lease: str) -> LeaseChangeResult:
        """Extend renew_by of the bound caller's own lease."""
        raise NotImplementedError

    def release(self, lease: str) -> LeaseChangeResult:
        """End the bound caller's own lease now."""
        raise NotImplementedError

    def observe(self, cursor: str, wait_ms: int) -> ObserveResult:
        """Yield requests addressed to the bound caller since cursor, waiting up to
        wait_ms (0..30000) for one. Each request names the lease to yield. A
        holder that never observes is asked through its adapter when the service
        has one, and is otherwise recorded as unanswered."""
        raise NotImplementedError

    def answer(self, request: str, answer: YieldAnswer | None, reason: str) -> AnswerCallResult:
        """Record the bound caller's answer to one yield request. yielded is
        checked against the instrument before the asker is told; a refusal
        carries its reason into the audit."""
        raise NotImplementedError

    def bind_process(self, lease: str, pid: int) -> ProcessBindResult:
        """Associate the bound caller's own lease with one directly spawned process
        when its process start identity, parent relation and account can be
        verified. A failed or unsupported verification returns unverifiable and
        keeps conservative reservation accounting. One process may bind to one
        live lease."""
        raise NotImplementedError


